sitemapindex:
{%- comment -%}
  1. Include the main site's own content sitemap (dynamically lookup the page with layout: sitemap_content).
{%- endcomment -%}
{%- assign main_sitemap_pages = site.pages | where: "layout", "sitemap_content" -%}
{%- assign main_sitemap = main_sitemap_pages.first -%}
{%- if main_sitemap -%}

  {{ main_sitemap.url | absolute_url }}
  {%- assign main_lastmod = main_sitemap.last_modified_at | default: main_sitemap.date | default: site.time -%}
  {{ main_lastmod | date_to_xmlschema }}

{%- endif -%}

{%- comment -%}
  2. Read custom subdomain sitemap URLs from _data/sitemaps.yml under 'sub_sitemaps' key.
{%- endcomment -%}
{%- assign sub_sitemaps = site.data.sitemaps.sub_sitemaps -%}
{%- if sub_sitemaps -%}
  {%- for item in sub_sitemaps -%}
    {%- assign url_loc = nil -%}
    {%- assign lastmod = nil -%}

    {%- if item.url or item.loc -%}
      {%- assign url_loc = item.url | default: item.loc -%}
      {%- assign lastmod = item.lastmod | default: item.last_modified_at | default: item.date -%}
    {%- else -%}
      {%- assign first_char = item | slice: 0 -%}
      {%- if first_char == "/" or item contains "http" -%}
        {%- assign url_loc = item -%}
      {%- else -%}
        {%- assign url_loc = nil -%}
      {%- endif -%}
    {%- endif -%}

    {%- if url_loc -%}

        {{ url_loc | absolute_url }}
        {%- if lastmod -%}
        {{ lastmod | date_to_xmlschema }}
        {%- endif -%}

    {%- endif -%}
  {%- endfor -%}
{%- endif -%}
